const E=ComboEngine,$=id=>document.getElementById(id);let s=E.defaults(),page='entry',selected=null,choiceSource=null,kioskAdded=null,kioskDecision=null,added=null,posDecision=null,confirmed=null,notice='',events=[],runId=crypto.randomUUID?crypto.randomUUID():String(Date.now()),start=performance.now(),lastExposure={},scenarioId='custom',posSkipped=null,payMethod=null;
const money=n=>'VND '+new Intl.NumberFormat('en-US').format(n);
const escapeHTML=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function log(event,detail={}){events.push({run_id:runId,at:new Date().toISOString(),elapsed_s:+((performance.now()-start)/1000).toFixed(3),event,channel:s.channel,branch:s.branch,screen:page,band:E.band(s),scenario:scenarioId,state:JSON.parse(JSON.stringify(s)),...detail});}
let toastTimer=null;function toast(t){$('toast').textContent=t;$('toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').style.display='none',3000)}
let menuCategory='all',customization={chicken:'Original',drink:'Pepsi'};
const categoryLabels={all:'Full Menu',solo:'Meals for One',group:'Sharing Meals',chicken:'Fried / Roasted Chicken',rice:'Burgers / Rice / Pasta',side:'Snacks & Sides'};
const photoMap={classic:'chicken-combo.jpg',ready:'rice-combo.jpg',light:'burger-combo.jpg',promo:'pasta-combo.jpg',solo:'solo-combo.jpg',group:'group-combo.jpg',single:'sides.jpg',side:'popcorn.jpg',drink:'pepsi.jpg',salad:'salad.jpg',dessert:'tart.jpg',fries:'fries.jpg',cheese:'cheese.jpg',potato:'potato.jpg',tart:'tart.jpg',pasta2:'pasta-share.jpg',bucket2:'bucket.jpg',shrimp2:'shrimp-combo.jpg',rice1:'rice-combo.jpg',burger1:'burger-combo.jpg',pasta1:'pasta-combo.jpg',family:'bucket.jpg',familyrice:'rice-combo.jpg',riceMain:'rice-main.jpg',burgerMain:'burger-main.jpg',chickenMain:'chicken-main.jpg'};
const assetUrls={"chicken-main.jpg":"assets/chicken-main.jpg","burger-main.jpg":"assets/burger-main.jpg","shrimp-combo.jpg":"assets/shrimp-combo.jpg","bucket.jpg":"assets/bucket.jpg","pasta-share.jpg":"assets/pasta-share.jpg","rice-main.jpg":"assets/rice-main.jpg","salad.jpg":"assets/salad.jpg","cheese.jpg":"assets/cheese.jpg","popcorn.jpg":"assets/popcorn.jpg","fries.jpg":"assets/fries.jpg","potato.jpg":"assets/potato.jpg","tart.jpg":"assets/tart.jpg","pepsi.jpg":"assets/pepsi.jpg","chicken-combo.jpg": "assets/chicken-combo.jpg", "group-combo.jpg": "assets/group-combo.jpg", "sides.jpg": "assets/sides.jpg", "kfc-logo.svg": "assets/kfc-logo.svg", "solo-combo.jpg": "assets/solo-combo.jpg", "pasta-combo.jpg": "assets/pasta-combo.jpg", "drinks.jpg": "assets/drinks.jpg", "rice-combo.jpg": "assets/rice-combo.jpg", "burger-combo.jpg": "assets/burger-combo.jpg"};
const displayNames={classic:'Crispy Chicken Combo',ready:'Chicken Rice Combo',light:'Burger Combo',promo:'Chicken & Pasta Combo',solo:'Solo Combo',group:'Group Combo',single:'Light Meal',side:'Popcorn Chicken',drink:'Drink Pair',salad:'Sesame Salad',dessert:'Dessert Pair'};
[...E.meals,...E.addons].forEach(x=>{x.name=displayNames[x.id]||x.name;});
function foodPhoto(id){return `<img src="${assetUrls[photoMap[id]||'chicken-combo.jpg']}" alt="KFC reference photo for ${displayNames[id]||E.posCatalog.find(x=>x.id===id)?.name||E.meals.find(x=>x.id===id)?.name||'meal'}; demo contents may differ" loading="eager">`;}
function matchesCategory(x){return menuCategory==='all'||(menuCategory==='solo'&&x.people===1)||(menuCategory==='group'&&x.people>=2)||(menuCategory==='chicken'&&['classic','solo','group','bucket2','family'].includes(x.id))||(menuCategory==='rice'&&['ready','light','promo','pasta2','shrimp2','rice1','burger1','pasta1','familyrice'].includes(x.id))||(menuCategory==='side'&&x.id==='single');}
function showCategory(cat){if(page==='entry')s.hardBudget=false;menuCategory=cat;selected=null;choiceSource=null;log('category_selected',{category:cat});go('menu');}
function orderMode(mode){s.orderMode=mode;log('order_mode_changed',{mode});render();}
function cartReview(){if(page==='done')return;if(s.channel==='kiosk'&&selected){if(page==='review')go('payment');else if(page==='payment')return;else if(kioskDecision)go('review');else{const u=E.kioskUpsell(s,selected);log('basket_opened_without_extra',{offered:u.cards.map(x=>x.id)});kioskUpsellAct(u.cards.length?'SKIP':'NONE');}}else if(s.channel==='pos'&&page==='pos')posAct('REVIEW');}
function shell(body){if(s.channel==='kitchen')return body;const isKiosk=s.channel==='kiosk';const total=confirmed?confirmed.total:isKiosk?(selected?selected.price+(kioskAdded?kioskAdded.price:0):0):E.quotePOS(s,added).total;return `<div class="device kfc-device ${isKiosk?'kiosk-device':s.channel==='kitchen'?'kitchen-device':'pos-device'} ${page==='entry'?'entry-device':page==='intent'?'intent-device':''} ${page==='menu'?'menu-device':''} ${page==='review'?'review-device':''} ${['options','menu','customize'].includes(page)?'choice-device':''}"><div class="device-top"><span class="device-brand"><img src="assets/kfc-logo.svg" alt="KFC"><span>ComboFlow<small>YOUR CHOICE. YOUR CALL.</small></span></span><span>${isKiosk?'CUSTOMER KIOSK':s.channel==='kitchen'?'KITCHEN BOARD · DEMO':'STAFF POS · COUNTER 01'} <span class="pill">${s.branch}</span></span></div><div class="kiosk-layout">${isKiosk&&page==='menu'?`<aside class="category-nav" aria-label="Kiosk categories"><button class="kiosk-logo" aria-label="Kiosk home" onclick="resetRun()"><i class="kfc-stripes"></i><img src="assets/kfc-logo.svg" alt="KFC"></button><button class="assist-nav ${page!=='menu'?'selected':''}" onclick="startGuided()">✦ ComboFlow<br><small>Help me choose</small></button>${Object.entries(categoryLabels).map(([id,name])=>`<button class="${page==='menu'&&menuCategory===id?'selected':''}" onclick="showCategory('${id}')">${name}</button>`).join('')}<div class="nav-foot">Prototype<br>No real orders</div></aside>`:''}<div class="order-content">${isKiosk?`<div class="kfc-banner english-banner"><div class="banner-copy"><small>KFC × COMBOFLOW</small><strong>GOOD FOOD.<br>BETTER<br>TOGETHER.</strong><p>A meal for your moment.<br>Let’s find yours.</p></div><img src="assets/group-combo.jpg" alt="KFC chicken, burger and sides reference photo"><span>REFERENCE IMAGE · PROTOTYPE</span></div><div class="service-switch"><div><button class="${s.orderMode!=='takeaway'?'selected':''}" onclick="orderMode('dine')">♧ Dine in</button><button class="${s.orderMode==='takeaway'?'selected':''}" onclick="orderMode('takeaway')">▣ Take away</button></div><span>EN</span></div>`:''}${body}</div></div><div class="cart-bar"><button class="home-button" onclick="resetRun()">⌂ <span>Home</span></button><div class="cart-total"><small>Simulated total</small><b>${money(total)}</b></div><button class="btn red cart-button" ${page==='done'||(isKiosk?!selected||page==='payment':!E.quotePOS(s,added).valid)?'disabled':''} onclick="cartReview()">${isKiosk&&page==='review'?'Checkout':'View basket'} <span>→</span></button></div><div class="device-foot"><span>ComboFlow · Simulated decision support</span><span>Human confirmation required · No real payment</span></div></div>`;}
function steps(n){return `<div class="steps">${['01 Your needs','02 Combo + customize','03 Review','04 Pay'].map((x,i)=>`<span class="${i===n?'current':''}">${x}</span>`).join('<span>→</span>')}</div>`}
function pipeline(d){return `<div class="pipeline"><div><b>01 · Rules</b><span>${d.valid.length} valid fixtures</span></div><div><b>02 · Contextual Ranking</b><span>${d.fixed?'Bypassed · fixed order':'Heuristic decision table'}</span></div><div><b>03 · Load Gate</b><span>${d.band} · simulated</span></div><div><b>04 · Human Decision</b><span>Choose / ADD / SKIP → confirm</span></div></div>`}
function stateNotice(d){return `${notice?`<div class="notice" role="status">${escapeHTML(notice)}</div>`:''}${d.band==='Safe fallback'?'<div class="notice safe"><b>Rules-only safe fallback.</b> The signal is stale or ranking is unavailable. Fixed order only; no Fastest to Serve label or time promises.</div>':d.band==='High'?'<div class="notice"><b>High · simulated.</b> Upsell is paused. Main-meal choices remain subject to validity and serviceability checks. You decide.</div>':''}`}
function card(item,i,manual=false){return `<article class="card ${!i&&!manual?'featured':''} ${selected&&selected.id===item.id?'chosen':''}"><div class="card-label">${escapeHTML(manual?'Menu item':item.label)}${s.verifiedFixture&&!manual?' · synthetic test':''}</div><div class="food-art">${foodPhoto(item.id)}</div><div class="card-body"><h3>${item.name}</h3><p>${item.desc}</p><div class="price">${money(item.price)}</div><small class="verify">${E.VERIFY}<br>Simulated price & meal · Reference photo${s.verifiedFixture&&item.label&&item.label.includes('Best Value')?'<br>Synthetic saving: '+money(item.retail-item.price):''}</small><button class="btn ${!i&&!manual?'red':'white'}" onclick="choose('${item.id}',${manual})">${selected&&selected.id===item.id?'Selected ✓':'Select combo →'}</button></div></article>`}
function render(){document.body.classList.toggle('kitchen-mode',s.channel==='kitchen');document.body.classList.toggle('pos-mode',s.channel==='pos');const d=decision();$('kioskTab').classList.toggle('active',s.channel==='kiosk');$('posTab').classList.toggle('active',s.channel==='pos');$('kitchenTab').classList.toggle('active',s.channel==='kitchen');document.querySelector('.simulation-right').textContent=`${s.branch} · No live orders`;let b='';
if(page==='done'){b=`<section class="screen success"><div class="tick">✓</div><p class="eyebrow">HUMAN DECISION COMPLETE</p><h2>Confirmed.<br>Your choice. Your call.</h2><p class="lead">${s.channel==='kiosk'?'Your choice':'Basket'} has been confirmed for this simulation.</p><div class="order-number"><small>DEMO ORDER NUMBER</small><b>#${confirmed.ticketId}</b><span>${confirmed.orderMode?escapeHTML(confirmed.orderMode)+' · ':''}Queued on the demo Kitchen Board</span></div>${confirmed.payment?`<p class="custom-receipt">Payment: ${escapeHTML(confirmed.payment)} · simulated, nothing charged</p>`:''}<div class="summary-row"><span>${escapeHTML(confirmed.label)}</span><b>${money(confirmed.total)}</b></div>${confirmed.customLabel?`<p class="custom-receipt">${escapeHTML(confirmed.customLabel)}</p>`:''}${s.channel==='kiosk'?comboSavings(null,null,confirmed.comboQuote):posSavings(confirmed.discount)}<small class="verify">${E.VERIFY}</small><div class="notice safe">No order is sent to KFC, a real POS or a real kitchen. The ticket exists only on this page’s demo Kitchen Board. No payment is taken.</div><div class="actions"><button class="btn red" onclick="resetRun()">Start a new session</button><button class="btn white" onclick="switchChannel('kitchen')">Track on Kitchen Board →</button><button class="btn white" onclick="switchChannel('${s.channel==='kiosk'?'pos':'kiosk'}')">Try ${s.channel==='kiosk'?'Staff POS':'Customer Kiosk'} →</button></div></section>`;}
else if(s.channel==='kitchen'){b=renderKitchenBoard();}
else if(s.channel==='pos'){b=renderPOS(d);}
else if(page==='entry'){b=`<section class="screen kiosk-entry"><div class="entry-title"><p class="eyebrow">WELCOME TO KFC</p><h1>How would you like to order?</h1><p class="muted">Your favorites. Or a little inspiration.</p></div><div class="entry-paths"><button class="choose-path guided-path" onclick="startGuided()"><span class="path-top"><span class="path-icon">✦</span><span class="path-tag">COMBOFLOW</span></span><strong>Help me choose</strong><span class="path-description">Three quick choices. A meal that fits you.</span><span class="path-cta">Help me choose <b>→</b></span></button><button class="choose-path manual-path" onclick="startManual()"><span class="path-icon">☷</span><strong>I know what I want</strong><span class="path-description">Go straight to the menu.</span><span class="path-cta">Browse the full menu <b>→</b></span></button></div><p class="micro entry-note">You choose. You confirm. Nothing is added automatically.</p></section>`;}
else if(page==='intent'){b=renderIntent();}
else if(page==='options'){expose(d);const active=selected;b=`<section class="screen combo-screen">${steps(1)}<p class="eyebrow">YOUR MEAL, ALL IN ONE PLACE</p><h2>Three picks. Your call.</h2>${intentSummary()}${stateNotice(d)}${d.cards.length?`<div class="combo-workspace"><div class="combo-list"><div class="section-number"><b>1</b><h3>Choose your combo</h3><span>${d.cards.length} suggested combos</span></div><div class="cards guided-cards ${d.cards.length===2?'two':''}">${d.cards.map((x,i)=>card(x,i)).join('')}</div></div>${renderPairing(active,false)}</div>`:`<div class="empty"><div class="symbol">↗</div><h3>No matching meal yet.</h3><p class="muted small">Edit your preferences or choose from the menu.</p><button class="btn red" onclick="go('intent')">Edit preferences</button></div>`}<p class="micro">${d.fixed?'Rules-only · fixed valid order.':s.verifiedFixture?'Best Value uses synthetic test values only; no verified KFC savings.':'Best Value is hidden because KFC prices and offers have not been verified.'} ${d.band==='Safe fallback'?'':'Fastest to Serve uses synthetic prep classes, not predicted wait times.'}</p><div class="actions"><button class="btn white" onclick="go('intent')">Edit preferences</button><button class="btn text" onclick="log('skip');go('menu')">Browse the full menu →</button></div></section>`;}
else if(page==='menu'){const menu=E.meals.filter(x=>!E.validity(x,s)&&matchesCategory(x)),active=selected;b=`<section class="screen combo-screen"><p class="eyebrow">YOUR ORDER, YOUR WAY</p><h2>${categoryLabels[menuCategory]}</h2><p class="muted small">Illustrative menu in a fixed order. ${s.hardBudget?'Your current budget limit still applies.':''}</p>${stateNotice(d)}${menu.length?`<div class="combo-workspace"><div class="combo-list"><div class="section-number"><b>1</b><h3>Choose your combo</h3></div><div class="cards">${menu.map((x,i)=>card(x,i,true)).join('')}</div></div>${renderPairing(active,true)}</div>`:'<div class="empty">No valid items. Adjust the budget or test scenario.</div>'}<button class="btn white" onclick="startGuided()">Help me choose / Edit budget</button></section>`;}
else if(page==='customize'){b=renderCustomize(d);}
else if(page==='review'){b=`<section class="screen checkout-screen">${steps(2)}<p class="eyebrow">HUMAN CHECKPOINT</p><h2>Your meal, all together.</h2><p class="muted small">Review your selection. ComboFlow never confirms automatically.</p>${stateNotice(d)}${selectedStatus(kioskAdded?'Combo + add-on selected':'Combo selected')}${comboSavings(selected,kioskAdded)}<div class="summary-row receipt-item"><div class="receipt-photo">${foodPhoto(selected.id)}</div><div><h3>${selected.name}</h3><span class="small muted">${selected.desc}</span><p class="custom-receipt">${customSummary()} · ${s.orderMode==='takeaway'?'Take away':'Dine in'}</p><small class="verify">${E.VERIFY}</small></div><b>${money(selected.price)}</b></div>${kioskAdded?`<div class="summary-row receipt-item"><div class="receipt-photo">${foodPhoto(kioskAdded.id)}</div><span>${kioskAdded.name}<small class="verify">${E.VERIFY}</small></span><b>${money(kioskAdded.price)}</b></div>`:'<p class="micro">You chose to continue without a side.</p>'}<div class="summary-row"><b>Illustrative total</b><b>${money(selected.price+(kioskAdded?kioskAdded.price:0))}</b></div><div class="actions"><button class="btn red" onclick="go('payment')">Continue to payment →</button><button class="btn white" onclick="undoKioskUpsell()">Edit side</button><button class="btn text" onclick="go('${choiceSource==='manual'?'menu':'options'}')">Change main meal</button></div><p class="micro">Nothing is charged here. You choose how to pay on the next step. Validity is checked again when you place the order.</p></section>`;}
else if(page==='payment'){b=renderPayment(d);}
if(s.channel==='pos')b=`<div class="pos-dual-layout"><div class="staff-display">${b}</div>${renderCustomerDisplay(d)}</div>`;$('app').innerHTML=shell(b);renderLab(d);$('scenario').value=scenarioId;if(s.channel==='kitchen'&&$('kitchenDetail'))$('kitchenDetail').showModal();}
function decision(){const d=E.decide(s);return s.channel==='pos'?KP.posAdvice(d,kitchenTickets,ingredientStock,s.posLines,E.band(s)!=='Safe fallback'&&!s.stockStale,KP.rankableReady(readyExtras,readyAge)):d;}
function renderPOSLoad(d){const loads=d.loads||[],max=Math.max(1,...loads.map(x=>x.total));return `<details class="pos-load"><summary class="workload-summary"><span>Kitchen workload <small>7 stations · synthetic counts</small></span><b>View prep details ↓</b></summary><div class="pos-load-content"><div class="pos-load-head"><div><p class="eyebrow">CONNECTED DEMO QUEUE</p><h3>Kitchen workload</h3></div><button class="btn white" onclick="switchChannel('kitchen')">Open Kitchen Board →</button></div><div class="station-cards">${loads.map(st=>`<div><strong>${st.name}</strong><b>${st.total}<small> prep units</small></b><span>${st.queued} queued · ${st.preparing} preparing</span><i style="--station-fill:${st.total/max*100}%"></i></div>`).join('')}</div><p class="micro">${d.band==='Safe fallback'?'Snapshot stale or unavailable · workload ranking paused. Rules-only fallback.':'Calculated from the same demo tickets shown on Kitchen Board.'} Recipe-unit counts, not minutes or utilization. ${E.VERIFY}</p><details><summary>View queued and preparing menu items</summary><div class="pos-queue-items">${queueMenuItems()}</div></details></div></details>`;}
function queueMenuItems(){const counts={};for(const t of kitchenTickets.filter(t=>t.status!=='ready'))for(const l of t.lines){const x=counts[l.id]||(counts[l.id]={queued:0,preparing:0});x[t.status]+=l.qty;}return Object.entries(counts).map(([id,n])=>`<span><b>${E.posCatalog.find(x=>x.id===id)?.name||E.meals.find(x=>x.id===id)?.name||id}</b>${n.queued} queued · ${n.preparing} preparing</span>`).join('')||'No open items.';}
function upsellReason(d,rec){return d.queueAware&&rec.readyCount>0?`Ready-item snapshot: ${rec.readyCount} available portions. Stock also covers queued demand. Staff must check holding quality before offering.`:d.queueAware?`Uses ${rec.stationNames.join(' / ')}: ${rec.pressure} open prep units. Adds ${rec.workUnits} recipe ${rec.workUnits===1?'unit':'units'}. Stock covers the queued orders, this basket and the extra.`:d.fixed?'Fixed valid order; workload ranking is paused. Check preparation with the kitchen.':'Compatible with this basket.';}
function selectedStatus(label){return `<div class="selection-green" role="status"><span>✓</span><b>${escapeHTML(label)}</b></div>`;}
function comboSavings(meal,extra=null,snapshot=null){const q=snapshot||E.comboQuote(meal,extra);if(!q||q.saving===null||q.saving<=0)return '';return `<div class="savings-green"><span class="savings-kicker">DEMO COMPARISON</span><strong>You save ${money(q.saving)}<br><span>with this combo</span></strong><p>Illustrative separate-item total <s>${money(q.comparison)}</s> · Selected total ${money(q.total)}</p><small>Simulated comparison, not a verified KFC saving. ${E.VERIFY}${extra?' Extra priced equally in both totals.':''}</small></div>`;}
function posSavings(discount){return discount>0?`<div class="savings-green"><span class="savings-kicker">DEMO OFFER APPLIED</span><strong>You save ${money(discount)}<br><span>on this order</span></strong><small>Illustrative discount, not a live KFC offer. ${E.VERIFY}</small></div>`:`<p class="no-savings">No discount applied. Any eligible demo offer must be selected by staff.</p>`;}
function customerOrderSnapshot(){const q=E.quotePOS(s,added);return {lines:[...q.lines.map(l=>({id:l.item.id,name:l.item.name,price:l.item.price,qty:l.qty,extra:false})),...(added?[{id:added.id,name:added.name,price:added.price,qty:1,extra:true}]:[])],subtotal:q.subtotal,discount:q.discount,total:q.total};}
function renderCustomerDisplay(d){const done=page==='done',order=done&&confirmed?.customerOrder?confirmed.customerOrder:customerOrderSnapshot(),rec=!done&&page==='pos'?posRec(d):null;return `<aside class="customer-preview" aria-label="Parallel customer display"><div class="display-label"><span>02 / CUSTOMER DISPLAY</span><small>Synchronized demo preview</small></div><div class="customer-monitor"><header><img src="assets/kfc-logo.svg" alt="KFC"><span>YOUR ORDER.<br>YOUR WAY.</span></header><div class="customer-monitor-body"><p class="eyebrow">${done?'DEMO ORDER CONFIRMED':page==='review'?'PLEASE CHECK YOUR ORDER':'LET’S MAKE IT YOURS'}</p><h2>${done?'Thank you!':'Looking good.'}</h2>${done&&confirmed?.ticketId?`<p class="customer-order-number">Order <b>#${confirmed.ticketId}</b></p>`:''}<p class="customer-help">${done?'Your demo order is confirmed. No payment has been taken.':page==='review'?'Check your items and total with our team before they confirm.':'Your choices appear here as our team adds them.'}</p>${!done&&page==='pos'?customerPicks():''}<div class="customer-items">${order.lines.length?order.lines.map(l=>`<div class="customer-item ${l.extra?'extra-selected':''}"><img src="${assetUrls[photoMap[l.id]||'chicken-combo.jpg']}" alt=""><span><strong>${l.qty} × ${escapeHTML(l.name)}</strong><small>${l.extra?'✓ Extra selected':money(l.price)+' each'}</small></span><b>${money(l.price*l.qty)}</b></div>`).join(''):'<p>Your basket is empty. Tell our team what you would like.</p>'}</div>${order.discount?`<div class="customer-subtotal"><span>Subtotal</span><b>${money(order.subtotal)}</b></div><div class="customer-discount"><span>Demo discount</span><b>− ${money(order.discount)}</b></div>`:''}<div class="customer-total"><span>${done?'Confirmed total':'Your total'}</span><strong>${money(order.total)}</strong></div>${order.discount?posSavings(order.discount):'<p class="customer-no-discount">No discount applied</p>'}${rec?`<div class="customer-suggestion"><div><small>ONE OPTIONAL EXTRA · NOT ADDED</small><h3>Make it yours.</h3><strong>Just ${money(rec.price)} more</strong><p>${escapeHTML(rec.name)}</p><em class="pair-with">${s.posLines.length?'Goes well with your '+escapeHTML(E.posCatalog.find(x=>x.id===s.posLines.at(-1).id)?.name||'order'):''}</em><span class="would-total">Your total would be ${money(E.quotePOS(s,rec).total)}</span><span>Ask our team to add it, or skip.</span></div><img src="${assetUrls[photoMap[rec.id]]}" alt="${escapeHTML(rec.name)} reference photo"></div>`:''}<div class="customer-checkpoint">${done?'✓ Confirmed by our team':page==='review'?'Awaiting your agreement and staff confirmation':'Nothing is added automatically'}</div><small class="customer-disclosure">${E.VERIFY} · Menu, images and prices are illustrative. No real orders or payment.</small></div></div></aside>`;}
function renderPOS(d){const rec=posRec(d),q=E.quotePOS(s,added);if(page==='pos'&&!posDecision)expose({...d,cards:rec?[rec]:[]});return `<section class="screen counter-screen"><div class="counter-title"><div><p class="eyebrow">KFC × COMBOFLOW · COUNTER 01</p><h2>Make every order count.</h2></div><span class="counter-session">COUNTER 01 <b>● DEMO SHIFT</b></span></div><div class="counter-sectionbar"><span class="active">Order workspace</span><span>Menu · Basket · One suggestion</span></div>${renderKitchen(d)}${renderPOSLoad(d)}${stateNotice(d)}${posIntentPanel()}<div class="counter-layout"><div class="counter-menu"><div class="section-number"><b>2</b><h3>Build the basket</h3></div><div class="menu-filter">${[['all','All items'],['combo','Combos'],['main','Meals'],['side','Sides'],['drink','Drinks'],['dessert','Desserts']].map(([v,t])=>`<button class="${posCategory===v?'selected':''}" onclick="filterPOS('${v}')">${t}</button>`).join('')}</div><div class="counter-menu-grid">${E.posCatalog.filter(x=>posCategory==='all'||x.category===posCategory).map(x=>{const why=E.validity(x,s);return `<button class="counter-food" ${why||page==='review'?'disabled':''} onclick="changePOS('${x.id}',1)"><div class="food-art">${foodPhoto(x.id)}</div><strong>${x.name}</strong><span>${money(x.price)}</span><small>${why||'Add to basket'}</small></button>`;}).join('')}</div><small class="verify">${E.VERIFY} · All menu prices and portions are illustrative.</small></div><div class="counter-order"><div class="basket"><div class="section-number"><b>3</b><h3>Current basket</h3><span>${q.lines.reduce((n,l)=>n+l.qty,0)} items</span></div>${q.lines.length?q.lines.map(l=>`<div class="counter-line"><div><strong>${l.item.name}</strong><small>${money(l.item.price)} each</small></div><div class="qty-controls"><button aria-label="Remove one ${l.item.name}" ${page==='review'?'disabled':''} onclick="changePOS('${l.item.id}',-1)">−</button><b>${l.qty}</b><button aria-label="Add one ${l.item.name}" ${page==='review'?'disabled':''} onclick="changePOS('${l.item.id}',1)">+</button></div><b>${money(l.item.price*l.qty)}</b></div>`).join(''):'<p class="small muted">Choose a meal from the menu to start.</p>'}${added?`<div class="basket-row accepted-extra"><span>✓ ${added.name}<small>Accepted upsell</small></span><b>${money(added.price)}</b></div>`:''}${q.discount?`<div class="basket-row discount-line"><span>Demo offer applied</span><b>− ${money(q.discount)}</b></div>`:''}<div class="summary-row"><b>Order total</b><b>${money(q.total)}</b></div>${added?selectedStatus(added.name+' added'):''}${posSavings(q.discount)}</div><div class="demo-offer"><span class="offer-stamp">DEMO<br>OFFER</span><div><strong>Save ${money(10000)} on this order</strong><p>A side in a basket of ${money(150000)} or more. One offer per order.</p><small>${s.expired?'Expired · cannot be applied':q.eligible?'Eligible for this demo basket':'Not eligible yet · add a side and meet the minimum'}</small><label><input type="checkbox" ${s.applyPromo?'checked':''} ${!q.eligible?'disabled':''} onchange="applyPOSOffer(this.checked)"> Apply demo discount</label></div></div><div class="pos-widget ${!rec&&!posDecision&&page!=='review'?'suppressed':''}"><p class="eyebrow">COMBOFLOW · PRIORITY UPSELL</p>${page==='review'?`<span class="state">Human checkpoint</span><h3>${posDecision==='ADD'?'Extra accepted.':posDecision==='SKIP'?'Suggestion skipped.':'Basket ready for review.'}</h3><p class="small muted">Confirm the items, discount and total with the customer.</p><button class="btn red" ${!q.valid?'disabled':''} onclick="confirmOrder()">Confirm basket →</button><button class="btn text" onclick="undoPOS()">Back to basket</button>`:posDecision==='ADD'&&added?`<div class="priority-offer"><div class="food-art">${foodPhoto(added.id)}</div><div><span class="state">Customer said ADD</span><p class="addon-price">Just ${money(added.price)} more</p><h3>${added.name}</h3><p class="small muted">The extra stays in the basket while it remains valid. Keep editing the basket or review it with the customer.</p></div></div><div class="actions"><button class="btn red" ${!q.valid?'disabled':''} onclick="posAct('REVIEW')">Review basket →</button><button class="btn white" onclick="removeExtra()">Remove extra</button></div>`:posDecision==='SKIP'?`<span class="suppression-icon" aria-hidden="true">✓</span><h3>Suggestion skipped</h3><p class="small muted">One optional extra per order. It will not be offered again unless staff reopens it at the customer’s request.</p><div class="actions"><button class="btn red" ${!q.valid?'disabled':''} onclick="posAct('REVIEW')">Review basket →</button><button class="btn white" onclick="reopenSuggestion()">Show suggestion again</button></div>`:rec?`<div class="priority-offer"><div class="food-art">${foodPhoto(rec.id)}</div><div><span class="state">${d.fixed?'Rules-only valid option':'First suggestion'}</span><p class="addon-price">Just ${money(rec.price)} more</p><h3>${rec.name}</h3><p class="small muted">${rec.category==='drink'?'A drink is missing.':rec.category==='side'?'A side is missing.':'A sweet finish is missing.'} ${upsellReason(d,rec)}</p></div></div><div class="upsell-evidence"><b>${d.queueAware?(rec.readyCount>0?'Ready to pair · check with kitchen':rec.pressure===0?'Quiet station · easy to add':rec.prepMatch>0?'Shared prep candidate · team check':'Lowest eligible station workload'):'Rules-only safe choice'}</b><span>${d.band==='Safe fallback'?'Ingredient coverage needs a manual check.':(d.stockRejected?.length||0)+' alternatives excluded by ingredient checks.'} Customer may ADD or SKIP.</span></div><small class="verify">${E.VERIFY} · Simulated serviceability.</small><div class="actions"><button class="btn red" onclick="posAct('ADD')">ADD</button><button class="btn white" onclick="posAct('SKIP')">SKIP</button></div>`:`<span class="suppression-icon" aria-hidden="true">⊘</span><h3>No recommendation</h3><p class="small muted">${d.band==='High'?'Kitchen load is High. Upsell is paused; continue the customer’s order without an extra.':!E.posHasBase(s)?(s.orderType==='snack'?'Add a snack to start.':'Start with a main meal or a combo.'):s.override==='suppress'?'The manager has paused suggestions.':d.stockRejected?.length?'Ingredient check: queued orders and this basket already use the available stock, so no extra is offered. Continue the order.':'No compatible, valid extra remains for this kitchen state.'}</p><button class="btn red" ${!q.valid?'disabled':''} onclick="posAct('REVIEW')">Review basket →</button>`}</div></div></div><p class="micro">One prioritized suggestion at a time. Menu choices remain manual. Kitchen bands and offers are demo assumptions, not live operational data or real KFC promotions.</p></section>`;}

function expose(d,scope='main',context=null){const key=JSON.stringify([runId,page,s.branch,d.band,context,d.cards.map(x=>[x.id,x.label])]);if(lastExposure[scope]!==key){log('recommendation_shown',{stage:scope,context_meal:context,options:d.cards.map((x,i)=>({id:x.id,position:i+1,label:x.label,open_prep_units:x.pressure,stations:x.stationNames})),stock_rejected:d.stockRejected||[],alternatives:[],no_recommendation:!d.cards.length});lastExposure[scope]=key;}}
function renderLab(d){$('lab').innerHTML=`<p class="eyebrow">FACILITATOR ONLY</p><h2>Scenario lab</h2><p class="small muted">Change inputs to inspect the decision.<br>All states below are [Assumption].</p><label for="scenario">Scenario preset · starts a new run</label><select id="scenario" onchange="scenario(this.value)"><option value="custom">Custom / current state</option><option value="normal">01 · Kiosk / two people</option><option value="value">02 · Three-card synthetic fixture</option><option value="high">03 · High load / POS</option><option value="expired">04 · Promotion expired</option><option value="unavailable">05 · Item unavailable</option><option value="stale">06 · Stale kitchen signal</option><option value="none">07 · No eligible recommendation</option><option value="group">08 · Group of four</option><option value="budget">09 · Low budget / single item</option><option value="ranking">10 · Ranking unavailable</option><option value="stock">11 · Stock data stale</option></select><label for="branch">Prototype branch</label><select id="branch" onchange="setState('branch',this.value)"><option value="C_sim" ${s.branch==='C_sim'?'selected':''}>C_sim · contextual heuristic</option><option value="B" ${s.branch==='B'?'selected':''}>B · Rules-only / fixed order</option></select><hr><label>Observed-load band · simulated</label><div class="band-buttons">${['Normal','Elevated','High','Safe fallback'].map(x=>`<button class="${d.band===x?'selected':''}" onclick="setBand('${x}')">${x}</button>`).join('')}</div><div class="metric"><span>Median waiting-ticket age</span><b>${s.age}s</b></div><div class="metric"><span>Signal age</span><b>${s.freshness}s</b></div><p class="micro">${d.band==='High'?'Fixture: ≥120s sustained for 120s.':d.band==='Safe fallback'?'Stale >60s, ranking unavailable or manager safe mode.':'Normal <90s · Elevated ≥90s; High requires persistence.'} Not a predicted wait or safe capacity threshold. Kiosk fixture: At Elevated/High, the synthetic item snapshot changes Classic share to Normal prep and Easy share to Ready now.</p><label class="check"><input type="checkbox" ${s.expired?'checked':''} onchange="setState('expired',this.checked)">Promotion expired</label><label class="check"><input type="checkbox" ${s.unavailable.includes(s.channel==='kiosk'?'classic':'drink')?'checked':''} onchange="toggleUnavailable(this.checked)">Item unavailable ${s.channel==='kiosk'?'(Crispy Chicken Combo)':'(Drink Pair)'}</label>${['Spicy','Mirinda'].map(v=>`<label class="check"><input type="checkbox" ${(s.unavailableVariants||[]).includes(v)?'checked':''} onchange="toggleVariant('${v}',this.checked)">${v} unavailable (kiosk variant)</label>`).join('')}<label class="check"><input type="checkbox" ${s.rankingDown?'checked':''} onchange="setState('rankingDown',this.checked)">Ranking unavailable</label><label class="check"><input type="checkbox" ${s.stockStale?'checked':''} onchange="setState('stockStale',this.checked)">Stock data stale</label><label class="check"><input type="checkbox" ${s.verifiedFixture?'checked':''} onchange="setState('verifiedFixture',this.checked)">Synthetic value fixture (NOT verified KFC data)</label><hr><details><summary class="small"><b>Manager override · simulation</b></summary><label for="override">Action</label><select id="override"><option value="safe">Force Rules-only safe mode</option><option value="suppress">Suppress add-on recommendations</option><option value="none">Rollback to scenario policy</option></select><label for="reason">Reason required · no personal names</label><input id="reason" maxlength="160" placeholder="e.g. item preparation needs checking"><button class="btn white" style="margin-top:9px" onclick="managerOverride()">Apply & log</button><p class="micro">Cannot bypass validity. No real manager authentication in this prototype.</p></details><details class="trace"><summary>Main meal / POS · Input → Process → Output</summary><ol><li>Rules: ${d.valid.length} valid / ${d.rejected.length} removed.</li><li>${d.fixed?'Fixed order; contextual ranking bypassed.':'Contextual heuristic: minimum Fit / compatibility first.'}</li><li>Load Gate: ${d.band}.</li><li>Output: ${d.cards.map(x=>x.id).join(', ')||'No recommendation'}.</li><li>Human action required.</li></ol><p>Business Value omitted: contribution data unavailable.</p></details>${selected?`<details class="trace"><summary>Kiosk side · decision trace</summary><p>Input: ${selected.id}; ${budgetSummary()}. Compatibility: exclude included categories; apply total budget.</p><p>Load Gate: ${E.band(s)}. Eligible add-ons: ${E.kioskUpsell(s,selected).eligible.map(x=>x.id).join(", ")||"none"}.</p><p>Output: ${E.kioskUpsell(s,selected).cards.map(x=>x.id).join(", ")||"No recommendation"}. ADD / SKIP → confirm.</p></details>`:''}<hr><div class="lab-actions"><button class="btn white" onclick="exportLog()">Export session log ↓</button><button class="btn white" onclick="resetRun()">Reset run</button></div><p class="micro">${events.length} events in memory. Export before closing.<br>No research results or participant records prefilled.</p><a class="small" href="validation.html" target="_blank">Decision table, test kit & 2-min demo ↗</a>`;}
function go(next){if(next==='payment'&&(s.channel!=='kiosk'||!selected||!kioskDecision))return;if(next!=='payment')payMethod=null;if(next==='intent'){selected=kioskAdded=null;kioskDecision=null;if(!s.budgetBand)Object.assign(s,E.budgetPreset(s.party,'low'));}if(page==='done'&&next!=='done')newRun();if(next==='menu'&&page==='entry')s.hardBudget=false;page=next;notice='';log('screen_view');render();$('app').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}
function intent(key,value){s[key]=value;if(key==='party')Object.assign(s,E.budgetPreset(value,s.budgetBand||'low'));selected=kioskAdded=null;kioskDecision=null;log('intent_changed',{field:key,value});render();}
function switchChannel(c){kitchenPanel=null;priorityDraft=null;ticketPage=0;menuCategory='all';scenarioId='custom';if(page!=='done')log('run_stopped',{reason:'channel_switch'});const load=sharedLoad();s=E.defaults();Object.assign(s,load);s.channel=c;page=c==='kitchen'?'kitchen':c==='pos'?'pos':'entry';newRun();render();}
function newRun(){runId=crypto.randomUUID?crypto.randomUUID():String(Date.now());start=performance.now();selected=kioskAdded=added=confirmed=null;choiceSource=kioskDecision=posDecision=posSkipped=payMethod=null;notice='';lastExposure={};log('run_started');}
function resetRun(){menuCategory='all';scenarioId='custom';if(page!=='done')log('run_stopped',{reason:'reset'});const channel=s.channel,load=sharedLoad();s=E.defaults();Object.assign(s,load);s.channel=channel;page=channel==='kitchen'?'kitchen':channel==='pos'?'pos':'entry';newRun();render();}
function setState(key,value){s[key]=value;log('state_changed',{field:key,value});revalidate();render();}
function setBand(b){s.age=b==='Normal'?45:b==='Elevated'?100:135;s.freshness=b==='Safe fallback'?75:5;s.highSeconds=b==='High'?120:0;s.previousHigh=false;s.recoverySeconds=0;s.rankingDown=false;feedLost=b==='Safe fallback';kitchenTickets=seedKitchen(s.age);log('state_changed',{field:'load_fixture',value:b});revalidate();render();}
function toggleVariant(id,on){s.unavailableVariants=on?[...new Set([...(s.unavailableVariants||[]),id])]:(s.unavailableVariants||[]).filter(x=>x!==id);log('state_changed',{field:'unavailableVariants',value:s.unavailableVariants});revalidate();render();}
function toggleUnavailable(on){const id=s.channel==='kiosk'?'classic':'drink';s.unavailable=on?[...new Set([...s.unavailable,id])]:s.unavailable.filter(x=>x!==id);log('state_changed',{field:'unavailable',value:s.unavailable});revalidate();render();}
function revalidate(){if(page==='done')return;if(s.channel==='pos'){const valid=s.posLines.filter(l=>!E.validity(E.posCatalog.find(x=>x.id===l.id),s));if(valid.length!==s.posLines.length){s.posLines=valid;syncPOS();posDecision=null;page='pos';notice='An unavailable or expired item was removed. Review the basket again.';log('basket_invalidated');}}const d=decision();if(selected&&(E.validity(selected,s)||(choiceSource!=='manual'&&!d.eligible.some(x=>x.id===selected.id)))){notice='Conditions have changed. Please choose a valid meal again.';log('selection_invalidated',{id:selected.id});selected=kioskAdded=null;kioskDecision=null;page=choiceSource==='manual'?'menu':'options';}if(kioskAdded&&(!selected||!E.kioskUpsell(s,selected).eligible.some(x=>x.id===kioskAdded.id))){notice='The side is no longer eligible and has been removed. Choose again or skip.';log('selection_invalidated',{id:kioskAdded.id,stage:'kiosk_upsell'});kioskAdded=null;kioskDecision=null;page=choiceSource==='manual'?'menu':'options';}if(added&&(E.validity(added,s)||!d.eligible.some(x=>x.id===added.id))){notice='The add-on is no longer eligible and has been removed. Staff must choose again or SKIP.';log('selection_invalidated',{id:added.id});added=null;posDecision=null;page='pos';}if(s.channel==='pos'&&posDecision&&!E.posHasBase(s)){added=null;posDecision=posSkipped=null;page='pos';}if(s.channel==='pos')syncPromo();if(selected&&s.channel==='kiosk'){const bad=(selected.variantGroups||[]).filter(g=>!E.variants[g].some(v=>v.id===customization[g])||(s.unavailableVariants||[]).includes(customization[g]));if(bad.length){const prev=bad.map(g=>customization[g]).join(', ');Object.assign(customization,E.defaultVariants(selected,s));notice=prev+' is no longer available. We selected '+bad.map(g=>customization[g]).join(', ')+'. Please check your choice.';log('variant_invalidated',{previous:prev,replacement:bad.map(g=>customization[g])});if(page==='review'||page==='payment'){kioskDecision=null;kioskAdded=null;page='customize';}}}if(page==='options'||page==='pos')notice=notice||'Options have been updated for this simulated scenario.';}
function choose(id,manual){if(manual&&page==='entry')s.hardBudget=false;const item=E.meals.find(x=>x.id===id),d=decision();if(!item||E.validity(item,s)||(!manual&&!d.eligible.some(x=>x.id===id))){toast('This choice is no longer valid. Please choose again.');log('invalid_action',{id});render();return;}selected=item;kioskAdded=null;kioskDecision=null;customization=E.defaultVariants(item,s);choiceSource=manual?'manual':'recommendation';log(manual?'manual_choice':'choose',{id});page='customize';notice='';render();$('app').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}
function posAct(action){if(page!=='pos')return;const d=decision(),rec=posRec(d);if(action==='ADD'||action==='SKIP'){if(!rec)return;if(action==='ADD'){added=rec;log('add',{id:added.id});toast(added.name+' added. Keep editing or review the basket.');}else{added=null;posSkipped=rec.id;log('skip',{id:rec.id});}posDecision=action;render();return;}if(!E.quotePOS(s,added).valid){toast('Add a valid main meal before review.');return;}if(rec){toast('Ask the customer: ADD or SKIP the suggestion first.');log('review_blocked',{reason:'pending_suggestion'});return;}if(!posDecision){posDecision='NONE';log('continue_without_recommendation');}go('review');}
function removeExtra(){if(!added||page!=='pos')return;log('remove_addon',{id:added.id});posSkipped=added.id;added=null;posDecision='SKIP';syncPromo();render();}
function reopenSuggestion(){if(page!=='pos'||posDecision!=='SKIP')return;log('suggestion_reopened',{id:posSkipped});posSkipped=null;posDecision=null;render();}
function undoPOS(){log('back_to_basket',{extra:added?.id||null});if(posDecision==='NONE')posDecision=null;go('pos');}
function basketToggle(category,on){s.basket=on?[...new Set([...s.basket,category])]:s.basket.filter(x=>x!==category);log('basket_changed');revalidate();render();}
function confirmOrder(){const at=s.channel==='kiosk'?'payment':'review';if(page!==at)return;revalidate();if(page!==at){render();return;}if(s.channel==='kiosk'&&!payMethod){toast('Choose a payment method to continue.');return;}if(s.channel==='kiosk'&&(!selected||!kioskDecision))return;if(s.channel==='kiosk'&&E.variantValidity(selected,customization,s)){toast('Please choose an available flavor and drink.');log('confirmation_blocked',{reason:'variant_invalid'});go('customize');return;}if(s.channel==='pos'&&(!posDecision||!E.quotePOS(s,added).valid)){toast('Add a valid main meal before confirming.');return;}if(s.stockStale){toast('Availability is not confirmed. A manual check at the counter is required.');log('confirmation_blocked',{reason:'stock_stale'});return;}confirmed=s.channel==='kiosk'?{label:selected.name+(kioskAdded?' + '+kioskAdded.name:''),total:selected.price+(kioskAdded?kioskAdded.price:0),items:[selected.id,...(kioskAdded?[kioskAdded.id]:[])],customization:variantChoice(),customLabel:customSummary(),orderMode:s.orderMode==='takeaway'?'Take away':'Dine in',payment:payMethods.find(m=>m[0]===payMethod)[1],comboQuote:E.comboQuote(selected,kioskAdded)}:{label:added?'Counter order with '+added.name:'Counter order',total:E.quotePOS(s,added).total,items:[...s.posLines.map(x=>({...x})),...(added?[{id:added.id,qty:1}]:[])],discount:E.quotePOS(s,added).discount,customerOrder:customerOrderSnapshot()};confirmed.ticketId=enqueueKitchen(confirmed);log('confirm',{final_order:confirmed,output_valid:true});page='done';render();}
function managerOverride(){const reason=$('reason').value.trim(),mode=$('override').value;if(!reason){toast('Enter a reason before applying the override.');return;}s.override=mode;log('manager_override',{mode,reason});notice=mode==='none'?'The manager has restored the scenario policy.':'The manager override has been applied and logged.';revalidate();render();toast('Override logged · simulated manager');}
function scenario(id){scenarioId=id;if(page!=='done')log('run_stopped',{reason:'scenario_change'});s=E.defaults();page='options';if(id==='value'){s.verifiedFixture=true;s.priority='full';s.verifiedFixture=true;}if(id==='high'){s.channel='pos';s.age=135;s.highSeconds=120;page='pos';}if(id==='expired')s.expired=true;if(id==='unavailable')s.unavailable=['classic'];feedLost=id==='stale';if(id==='stale')s.freshness=75;if(id==='none'){s.channel='pos';s.basket=['main','drink','side','dessert'];s.posLines.push({id:'drink',qty:1},{id:'side',qty:1},{id:'tart',qty:1});page='pos';}if(id==='group'){s.party=4;s.budget=300000;s.budgetBand=null;}if(id==='budget'){s.party=1;s.budget=40000;s.budgetBand=null;s.priority='value';}if(id==='ranking')s.rankingDown=true;if(id==='stock')s.stockStale=true;kitchenTickets=seedKitchen(s.age);newRun();log('scenario_loaded',{preset:id});render();$('scenario').value=id;}
function toggleLab(){document.querySelector('.workspace').classList.toggle('lab-hidden');}
function exportLog(){log('log_export');const data={prototype:'ComboFlow',version:'1.14',disclosure:'Simulated Contextual Ranking (pre-scripted decision table)',data_type:'interaction trace from this browser; not a user-study result',events};const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download='comboflow-session-log.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000);toast('Session log exported');}
function budgetText(range,party){const low=party*100000,high=party*200000;return range==='low'?'Under '+money(low):range==='mid'?money(low)+' – '+money(high):'Over '+money(high);}
function budgetSummary(){return s.budgetBand?budgetText(s.budgetBand,s.party):s.hardBudget?'Up to '+money(s.budget):'No budget limit';}
function selectBudget(range){Object.assign(s,E.budgetPreset(s.party,range));selected=kioskAdded=null;kioskDecision=null;log('intent_changed',{field:'budgetBand',value:range});render();}
function startManual(){selected=kioskAdded=null;kioskDecision=null;s.hardBudget=false;s.budgetBand=null;menuCategory='all';log('entry_choice',{path:'manual'});go('menu');}
function startGuided(){selected=kioskAdded=null;kioskDecision=null;Object.assign(s,E.budgetPreset(s.party,s.budgetBand||'low'));log('entry_choice',{path:'guided'});go('intent');}
function intentSummary(){return `<div class="intent-visual"><div><span class="visual-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><circle cx="9" cy="7" r="3"/><path d="M3 21v-4a6 6 0 0 1 12 0v4M17 4a3 3 0 0 1 0 6M18 13a5 5 0 0 1 3 4v4"/></svg></span><span><small>PARTY SIZE</small><b>${s.party} ${s.party===1?'person':'people'}</b></span></div><div><span class="visual-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><rect x="2" y="5" width="20" height="15" rx="3"/><path d="M2 9h20M6 15h5"/></svg></span><span><small>YOUR BUDGET</small><b>${budgetSummary()}</b></span></div><div><span class="visual-icon">✦</span><span><small>YOUR PRIORITY</small><b>${{full:'Best Fit',fast:'Fastest to Serve',value:'Best Value'}[s.priority]}</b></span></div></div>`;}
function renderPairing(meal,manual){if(!meal)return '';const u=E.kioskUpsell(s,meal);expose(u,'kiosk_upsell',meal.id);return `<aside id="kiosk-addon" class="pairing-panel single-pairing" tabindex="-1" aria-label="One optional add-on"><div class="section-number"><b>2</b><h3>Best add-ons for this combo</h3><span>Optional</span></div><div class="pairing-context"><small>${selected?'YOUR SELECTED COMBO':'PAIRING PREVIEW · NOTHING ADDED'}</small><strong>✓ ${meal.name}</strong></div>${comboSavings(meal,kioskAdded)}${u.cards.length?`<p class="pairing-intro">One suggested pairing. Add it or continue with your combo.</p><div class="addon-grid">${u.cards.map((x,i)=>`<button class="addon-option" onclick="chooseBundle('${meal.id}','ADD',${manual},'${x.id}')"><span class="addon-tag">Suggested pairing</span><div class="food-art">${foodPhoto(x.id)}</div><span class="addon-price">Just ${money(x.price)} more</span><strong>${x.name}</strong><small>${x.desc}</small><span class="addon-action">Add this extra <b>→</b></span></button>`).join('')}</div>${s.hardBudget?'<p class="budget-caption">✓ This pairing fits your selected budget.</p>':''}<small class="verify">${E.VERIFY} · Illustrative items, portions and prices.</small><button class="btn white bundle-button" onclick="chooseBundle('${meal.id}','SKIP',${manual})">Skip extra · Combo only</button>`:`<div class="no-side-symbol">✓</div><p class="value-line">Your combo is<br>good to go.</p><p class="small muted">${u.reason==='high_load'?'The kitchen is busy. Upsell is paused; continue with your chosen combo.':u.reason==='safe_fallback'?'Optional extras are paused while the kitchen signal is unavailable.':u.reason==='manager_suppressed'?'Optional suggestions are currently paused.':'No eligible extra fits this meal, budget and simulated serviceability.'}</p><span class="state">No recommendation</span><button class="btn red bundle-button" onclick="chooseBundle('${meal.id}','NONE',${manual})">Continue with combo only →</button>`}<p class="micro">Nothing is added automatically. Review your full total before confirming.</p></aside>`;}

function chooseBundle(id,action,manual,addonId=null){const item=E.meals.find(x=>x.id===id),d=decision();if(!item||E.validity(item,s)||(!manual&&!d.eligible.some(x=>x.id===id))){toast('This choice is no longer valid. Please choose again.');render();return;}if(selected?.id!==item.id||E.variantValidity(item,customization,s))customization=E.defaultVariants(item,s);selected=item;kioskAdded=null;kioskDecision=null;choiceSource=manual?'manual':'recommendation';log(manual?'manual_choice':'choose',{id});kioskUpsellAct(action,addonId);}
function kioskUpsellAct(action,addonId=null){if(!['options','menu','customize'].includes(page)||!selected)return;revalidate();if(!['options','menu','customize'].includes(page)||!selected){render();return;}const u=E.kioskUpsell(s,selected);if(action==='ADD'){const option=u.cards.find(x=>x.id===addonId)||(!addonId?u.cards[0]:null);if(!option){render();return;}kioskAdded=option;log('add',{id:kioskAdded.id,stage:'kiosk_upsell'});}else{kioskAdded=null;log(action==='SKIP'?'skip':'continue_without_recommendation',{stage:'kiosk_upsell'});}kioskDecision=action;go('review');}
function undoKioskUpsell(){if(kioskAdded)log('remove_addon',{id:kioskAdded.id,stage:'kiosk_upsell'});kioskAdded=null;kioskDecision=null;go('customize');focusKioskAddon();}

let posCategory='all';
function syncPOS(){s.basket=[...new Set(s.posLines.flatMap(l=>{const x=E.posCatalog.find(x=>x.id===l.id);return x?(x.categories||[x.category]):[];}))];}
function changePOS(id,delta){const x=E.posCatalog.find(x=>x.id===id);if(!x||page==='review'||(delta>0&&E.validity(x,s)))return;const l=s.posLines.find(l=>l.id===id);if(l)l.qty+=delta;else if(delta>0)s.posLines.push({id,qty:1});s.posLines=s.posLines.filter(l=>l.qty>0);syncPOS();log('basket_changed',{id,delta,lines:s.posLines.map(l=>({...l}))});revalidate();render();}
function filterPOS(v){posCategory=v;render();}
function syncPromo(){if(s.applyPromo&&!E.quotePOS(s,added).eligible){s.applyPromo=false;notice='The demo offer was removed because the basket is no longer eligible. Staff must apply it again.';log('promotion_changed',{applied:false,reason:'no_longer_eligible'});}}
function applyPOSOffer(on){s.applyPromo=on&&E.quotePOS(s,added).eligible;log('promotion_changed',{applied:s.applyPromo});render();}
function renderKitchen(d){return `<div class="kitchen-dashboard" data-band="${d.band}"><div><span class="eyebrow">KITCHEN SIGNAL · SIMULATED</span><h3>${d.band}</h3><div class="load-segments">${['Normal','Elevated','High'].map(b=>`<span class="${b===d.band?'active':''}">${b}</span>`).join('')}</div></div><div class="kitchen-metric"><b>${s.age}<small>sec</small></b><span>Median waiting-ticket age</span></div><div class="kitchen-metric"><b>${s.freshness}<small>sec</small></b><span>Signal age</span></div><div class="kitchen-demo"><small>Preview a kitchen state</small><div>${['Normal','Elevated','High','Safe fallback'].map(b=>`<button aria-pressed="${b===d.band}" class="${b===d.band?'selected':''}" onclick="setBand('${b}')">${b}</button>`).join('')}</div></div><p>Shadow-mode assumptions · not a capacity estimate or customer wait promise. ${liveBadge()}</p><button class="btn white kitchen-status-btn" onclick="openStatus()">Manage kitchen status →</button></div>`;}
function moneyIcon(tier){return `<svg viewBox="0 0 88 52" width="88" height="52" fill="none" aria-hidden="true">${tier>1?'<path d="M12 8h65v36" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"/>':''}${tier>2?'<path d="M18 2h65v36" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"/>':''}<rect x="3" y="14" width="68" height="35" rx="5" stroke="currentColor" stroke-width="2.5"/><path d="M12 23h7m36 17h7" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"/><text x="37" y="38" text-anchor="middle" fill="currentColor" font-size="23" font-family="Roboto,sans-serif" font-weight="700">₫</text></svg>`;}
function focusKioskAddon(){requestAnimationFrame(()=>{const panel=$('kiosk-addon');if(!panel)return;panel.focus({preventScroll:true});panel.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});log('addon_panel_focused',{context_meal:selected?.id});});}
function peopleArt(n){return `<span class="people-art" aria-hidden="true">${Array.from({length:n},()=>'<i><b></b></i>').join('')}</span>`;}
function renderIntent(){return `<section class="screen intent-screen">${steps(0)}<div class="intent-heading"><div><p class="eyebrow">A MEAL THAT FEELS LIKE YOU</p><h2>Let’s find <em>your meal.</em></h2><p class="muted small">Your party. Your budget. Your priorities.</p></div><div class="intent-food">${foodPhoto('bucket2')}<span>LET’S EAT<br>TOGETHER.</span></div></div><div class="intent-section"><div class="section-number"><b>1</b><h3>Who’s joining?</h3></div><div class="visual-choices people-choices">${[1,2,4].map(n=>`<button class="${s.party===n?'selected':''}" aria-pressed="${s.party===n}" onclick="intent('party',${n})">${peopleArt(n)}<strong>${n===1?'Just me':n+' people'}</strong><small>${n===1?'My own little feast':n===2?'Better together':'Bring the whole crew'}</small><span class="choice-check">${s.party===n?'✓':'○'}</span></button>`).join('')}</div></div><div class="intent-section"><div class="section-number"><b>2</b><h3>Your comfort zone</h3><span>Whole-party budget</span></div><div class="visual-choices budget-choices">${['low','mid','high'].map((range,i)=>`<button class="${s.budgetBand===range?'selected':''}" aria-pressed="${s.budgetBand===range}" onclick="selectBudget('${range}')"><span class="budget-art" aria-hidden="true">${moneyIcon(i+1)}</span><small>${['Keep it light','A little more room','Make it a feast'][i]}</small><strong>${budgetText(range,s.party)}</strong><span class="choice-check">${s.budgetBand===range?'✓':'○'}</span></button>`).join('')}</div><p class="micro">Includes your meal and optional extra. Budget ranges adjust for your party. Spend only what feels right. Illustrative prices.</p></div><div class="intent-section"><div class="section-number"><b>3</b><h3>What do you prioritize?</h3></div><div class="visual-choices priority-choices">${[['fast','Fastest to Serve','◷','Keep things moving'],['full','Best Fit','✦','A meal that suits us'],['value','Best Value','◇','Make the budget count']].map(([v,t,icon,desc])=>`<button class="${s.priority===v?'selected':''}" aria-pressed="${s.priority===v}" onclick="intent('priority','${v}')"><span class="priority-icon" aria-hidden="true">${icon}</span><strong>${t}</strong><small>${desc}</small><span class="choice-check">${s.priority===v?'✓':'○'}</span></button>`).join('')}</div></div><div class="intent-footer"><button class="btn white" onclick="go('entry')">Back</button><p class="micro">No account needed.<br>Your choice stays yours.</p><button class="btn red" onclick="go('options')">Find my meal →</button></div></section>`;}

let kitchenPanel=null,ticketPage=0;
const KP=KitchenPlanner;let readyExtras={potato:3,tart:4,fries:0,salad:2},readyAge={potato:0,tart:0,fries:0,salad:0},ingredientStock=KP.stockDefaults(),incomingStock={},kitchenView='all',arrivalRate=1.2,completionRate=1,priorityDraft=null;
let ticketSeq=105;
let kitchenTickets=seedKitchen(45);
function sharedLoad(){return Object.fromEntries(['age','freshness','highSeconds','previousHigh','recoverySeconds','rankingDown'].map(k=>[k,s[k]]));}
function seedKitchen(age){return [0,1,2,3,4].map((i)=>({id:'D'+(101+i),age:Math.max(0,age+(i-2)*15),status:i<2?'preparing':'queued',channel:['Counter','Kiosk','Delivery','Counter','Kiosk'][i],label:['2 × Chicken Rice','Crispy Chicken Combo','Burger Combo','Chicken Rice Combo','Solo Combo'][i],fixture:true,lines:[[{id:'riceMain',qty:2}],[{id:'classic',qty:1}],[{id:'light',qty:1}],[{id:'ready',qty:1}],[{id:'solo',qty:1}]][i]}));}
function syncKitchen(elapsed=0,quiet=false){const wasHigh=s.previousHigh||(s.age>=120&&s.highSeconds>=120);s.age=E.medianTicketAge(kitchenTickets);if(s.age>=120)s.highSeconds+=elapsed;else s.highSeconds=0;if(wasHigh)s.previousHigh=true;if(s.previousHigh){s.recoverySeconds=s.age<90?s.recoverySeconds+elapsed:0;if(s.recoverySeconds>=300)s.previousHigh=false;}if(!quiet)log('kitchen_signal_updated',{open_tickets:kitchenTickets.filter(t=>t.status!=='ready').length,median_age:s.age});}
function enqueueKitchen(order){const lines=s.channel==='pos'?[...s.posLines.map(x=>({...x})),...(added?[{id:added.id,qty:1}]:[])]:[{id:selected.id,qty:1,variant:variantChoice()},...(kioskAdded?[{id:kioskAdded.id,qty:1}]:[])];const channel=s.channel==='pos'?'Counter':'Kiosk';let label=order.label+(s.channel==='kiosk'?' · '+customSummary()+' · '+order.orderMode:'');if(s.channel==='pos')label=E.quotePOS(s,added).lines.map(l=>l.qty+' × '+l.item.name).join(' · ')+(added?' · '+added.name:'');for(const l of lines)if(readyExtras[l.id])readyExtras[l.id]=Math.max(0,readyExtras[l.id]-l.qty);kitchenTickets.push({id:'D'+(++ticketSeq),age:0,status:'queued',channel,label,lines,fixture:false});syncKitchen();log('kitchen_ticket_created',{ticket_id:'D'+ticketSeq,source:channel});return 'D'+ticketSeq;}
function kitchenStep(id,next){const t=kitchenTickets.find(t=>t.id===id);if(!t||!((t.status==='queued'&&next==='preparing')||(t.status==='preparing'&&next==='ready')))return;if(next==='preparing'){const stock=KP.consume(t,ingredientStock);if(!stock){toast('Check ingredients before starting this ticket.');log('kitchen_start_blocked',{ticket_id:id});return;}ingredientStock=stock;log('ingredient_consumed',{ticket_id:id,needs:KP.needs(t.lines)});}const before=t.status;t.status=next;log('kitchen_human_action',{ticket_id:id,from:before,to:next});syncKitchen();render();}
function advanceKitchen(seconds){kitchenTickets.filter(t=>t.status!=='ready').forEach(t=>t.age+=seconds);for(const id in readyExtras)if(readyExtras[id]>0)readyAge[id]+=seconds;s.freshness+=seconds;syncKitchen(seconds);log('kitchen_demo_time_advanced',{seconds});render();}
function refreshKitchen(){feedLost=false;s.freshness=0;s.rankingDown=false;syncKitchen();log('kitchen_signal_refreshed');render();}

function kitchenPlan(){return KP.plan(kitchenTickets,ingredientStock,arrivalRate,completionRate,E.band(s)!=='Safe fallback');}
function setKitchenView(view){ticketPage=0;kitchenView=view;log('kitchen_group_viewed',{group:view});render();}
function draftPriority(group){priorityDraft=group;render();}
function confirmPriority(){const p=kitchenPlan(),group=p.groups[priorityDraft]||[];const ids=group.map(t=>t.id);kitchenTickets.forEach(t=>{t.teamPriority=ids.includes(t.id)?1:0;});log('kitchen_priority_confirmed',{group:priorityDraft,tickets:ids,reason:priorityDraft==='urgent'?'Oldest eligible tickets first':'Review next queued group'});priorityDraft=null;kitchenView='all';render();}
function changeForecast(key,value){if(key==='arrival')arrivalRate=Number(value);else completionRate=Number(value);log('forecast_assumption_changed',{key,value:Number(value)});render();}
function adjustStock(id,delta){if(!KP.ingredients.some(x=>x.id===id))return;ingredientStock[id]=Math.max(0,(ingredientStock[id]||0)+delta);log('ingredient_count_adjusted',{id,delta,on_hand:ingredientStock[id]});render();}
function planTopUp(id){const row=kitchenPlan().inventory.find(i=>i.id===id);if(!row||row.topUp===null||row.topUp<=0)return;incomingStock[id]=row.topUp;log('ingredient_topup_planned',{id,qty:incomingStock[id]});render();}
function receiveTopUp(id){const qty=incomingStock[id]||0;if(!qty)return;ingredientStock[id]+=qty;delete incomingStock[id];log('ingredient_topup_received',{id,qty});render();}
function resetIngredients(){ingredientStock=KP.stockDefaults();incomingStock={};log('ingredient_demo_reset');render();}
function forecastChart(p){if(!p.fresh)return '<div class="forecast-paused"><b>Forecast paused</b><p>Refresh the kitchen signal to explore a new scenario.</p></div>';const max=Math.max(10,...p.points.map(x=>x.high)),x=m=>45+m/15*490,y=v=>180-v/max*140;const points=key=>p.points.map(t=>x(t.min)+','+y(t[key])).join(' ');return `<svg class="forecast-chart" viewBox="0 0 560 220" role="img" aria-label="Illustrative open-ticket projection over 15 minutes; shaded area is a sensitivity scenario, not a confidence interval"><defs><linearGradient id="forecastFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#ed1537" stop-opacity=".2"/><stop offset="100%" stop-color="#ed1537" stop-opacity=".02"/></linearGradient></defs>${[0,.5,1].map(v=>`<line x1="45" y1="${y(max*v)}" x2="535" y2="${y(max*v)}" stroke="#eee9e5"/><text x="30" y="${y(max*v)+4}" text-anchor="end">${Math.round(max*v)}</text>`).join('')}<polygon points="${points('high')} ${[...p.points].reverse().map(t=>x(t.min)+','+y(t.low)).join(' ')}" fill="url(#forecastFill)"/><polyline points="${points('base')}" fill="none" stroke="#e41b35" stroke-width="3" stroke-linejoin="round"/>${p.points.map(t=>`<circle cx="${x(t.min)}" cy="${y(t.base)}" r="4" fill="#fff" stroke="#e41b35" stroke-width="2"/><text x="${x(t.min)}" y="205" text-anchor="middle">${t.min===0?'Now':'+'+t.min+' min'}</text>`).join('')}</svg>`;}
function kitchenTicket(t){const blocked=KP.shortage(t,ingredientStock),station=KP.station(t),active=t.status!=='ready';return `<article class="dispatch-ticket ${t.teamPriority?'team-priority':''} ${blocked.length&&t.status==='queued'?'stock-blocked':''}"><div class="ticket-top"><strong>#${t.id}</strong><span>${t.channel}</span><b class="ticket-age">${active?t.age+'s':'Ready ✓'}</b></div><div class="ticket-food"><div class="food-art">${foodPhoto(t.lines?.[0]?.id)}</div><div><small>${station}</small><p>${escapeHTML(t.label)}</p></div></div><div class="ticket-reason">${t.status==='ready'?'Completed by the team':t.status==='preparing'?'Preparation started by the team':blocked.length?'Stock check: '+blocked.map(b=>KP.ingredients.find(i=>i.id===b.id)?.name||'recipe').join(', '):t.teamPriority?'Team priority · confirmed':t.age>=60?'Priority candidate · waiting at least 60s':'Standard queue · review station needs'}</div><div class="ticket-meta"><span>${t.fixture?'Scenario fixture':'Confirmed demo order'}</span><b>${t.status==='queued'?'Queued':t.status==='preparing'?'Preparing':'Ready'}</b></div>${t.status!=='ready'?`<button class="btn ${t.status==='queued'?'white':'red'}" ${t.status==='queued'&&blocked.length?'disabled':''} onclick="kitchenStep('${t.id}','${t.status==='queued'?'preparing':'ready'}')">${t.status==='queued'?'Start preparing':'Mark ready'} →</button>`:''}</article>`;}
function inventoryCard(i){const alert=i.free<0?'short':i.free===0||i.cover!==null&&i.cover<5?'low':'good',pct=Math.min(100,i.onHand/Math.max(i.start,i.onHand,i.reserved,1)*100);return `<article class="ingredient-card ${alert}"><div class="ingredient-heading"><img src="${assetUrls[i.image]}" alt="${i.name} reference photo"><div><h4>${i.name}</h4><small>${i.unit} · demo count</small></div><span class="inventory-status">${i.free<0?'Short for queue':alert==='low'?'Watch stock':'In stock'}</span></div><div class="ingredient-count"><b>${i.onHand}</b><span>on hand</span><div class="stock-adjust"><button aria-label="Reduce ${i.name} count" onclick="adjustStock('${i.id}',-1)">−</button><button aria-label="Increase ${i.name} count" onclick="adjustStock('${i.id}',1)">+</button></div></div><div class="stock-meter"><span style="width:${pct}%"></span><i style="left:${Math.min(99,i.reserved/Math.max(i.start,i.onHand,i.reserved,1)*100)}%" title="Queued demand"></i></div><div class="ingredient-stats"><span>Queued demand <b>${i.reserved}</b></span><span>After queue <b>${i.free}</b></span><span>Next 10 min <b>${i.demand10===null?'—':i.demand10}</b></span></div><p class="stock-cover">${i.cover===null?(i.demand10===0?'No projected use in this order mix':'Forecast unavailable for this ingredient'):i.free<0?'Replenish before all queued orders can start':i.cover===0?'No unallocated cover in this scenario':'~'+i.cover+' min cover after queue · simulated'}</p>${incomingStock[i.id]?`<button class="stock-receive" onclick="receiveTopUp('${i.id}')">Receive ${incomingStock[i.id]} ${i.unit} →</button><small class="incoming-note">Planned only · not counted on hand</small>`:`<button class="stock-plan" ${i.topUp===null||i.topUp<=0?'disabled':''} onclick="planTopUp('${i.id}')">${i.topUp===0?'No top-up suggested':'Plan top-up'+(i.topUp>0?' · '+i.topUp+' '+i.unit:'')}</button>`}</article>`;}

function openKitchenPanel(type,id=null){kitchenPanel={type,id};render();}
function closeKitchenPanel(){kitchenPanel=null;priorityDraft=null;render();}
function kitchenDetail(p){let content='',title='';if(priorityDraft){title='Confirm group priority';content=`<p>Move ${(p.groups[priorityDraft]||[]).length} eligible tickets to the front?</p><p class="small muted">This changes display priority only. Each ticket still requires Start preparing and an ingredient check.</p><div class="actions"><button class="btn red" onclick="confirmPriority()">Confirm priority</button><button class="btn white" onclick="closeKitchenPanel()">Cancel</button></div>`;}else if(!kitchenPanel)return '';else if(kitchenPanel.type==='ready'){title='Ready-item snapshot';content=readyControls();}else if(kitchenPanel.type==='batch'){title='Review shared preparation';content=batchDetail();}else if(kitchenPanel.type==='ingredient'){const i=p.inventory.find(x=>x.id===kitchenPanel.id);title='Ingredient detail';content=inventoryCard(i);}else if(kitchenPanel.type==='ticket'){const t=kitchenTickets.find(x=>x.id===kitchenPanel.id);title='Ticket detail';content=t?kitchenTicket(t):'<p>Ticket no longer in this scenario.</p>';}else{title='Manage kitchen status';content=`<p class="small">All figures are synthetic. Load bands use Median waiting-ticket age; the forecast does not control the Load Gate.</p><div class="kitchen-controls gate-controls">${[['Normal','One compatible upsell. Prefer checked ready items.'],['Elevated','Prioritize ready items and quiet stations.'],['High','Pause every upsell. Keep taking orders.'],['Safe fallback','Fixed validity rules. No workload prediction.']].map(([b,t])=>`<button class="${E.band(s)===b?'selected':''}" onclick="setBand('${b}')"><b>${b}</b><span>${t}</span></button>`).join('')}</div><div class="actions"><button class="btn white" onclick="advanceKitchen(30)">Advance demo 30s</button><button class="btn white" onclick="refreshKitchen()">Refresh signal</button><button class="btn white" onclick="resetIngredients()">Reset demo counts</button><button class="btn white" onclick="openKitchenPanel('ready')">Manage ready items</button><button class="btn white" onclick="exportLog()">Export session log</button></div><p class="small muted">Scenario buttons reset tickets but retain edited ingredient counts. Time advances only when clicked. Signal older than 60s pauses forecasts. High requires 120s persistence; recovery requires 300s below 90s.</p><p class="small muted">Queue projection = max(0, open tickets + (arrivals − completions) × minutes). Shading varies arrivals ±25% and completions ±20%; it is not a confidence interval. Ingredient demand uses the current open-ticket recipe mix. No learned AI or real capacity estimate.</p><p class="small muted">Queued demand is reserved for planning. Start preparing deducts recipe quantities once; Ready does not deduct again. Plan top-up does not increase stock until Receive is clicked. Menu availability remains scenario-controlled; the ingredient ledger checks kitchen starts and fresh-signal POS upsell eligibility. Batch groups use shared recipe components; the team must check actual cooking compatibility.</p><small class="verify">${E.VERIFY} · No live KDS or inventory connection.</small>`;}return `<dialog id="kitchenDetail" class="kb-dialog" oncancel="event.preventDefault();closeKitchenPanel()"><div class="kb-dialog-head"><h2>${title}</h2><button aria-label="Close detail panel" onclick="closeKitchenPanel()">×</button></div>${content}</dialog>`;}
function renderKitchenBoard(){const p=kitchenPlan(),band=E.band(s),f=p.points[2],watch=p.inventory.filter(i=>i.free<0||i.cover!==null&&i.cover<5),filter=kitchenView==='urgent'?p.groups.urgent:kitchenView==='batch'?p.groups.batch:kitchenView==='blocked'?p.groups.blocked:kitchenTickets.filter(t=>kitchenView==='ready'?t.status==='ready':kitchenView==='preparing'?t.status==='preparing':t.status!=='ready'),all=[...filter].sort((a,b)=>(b.teamPriority||0)-(a.teamPriority||0)||b.age-a.age);ticketPage=Math.max(0,Math.min(ticketPage,Math.ceil(all.length/6)-1));const tickets=all.slice(ticketPage*6,ticketPage*6+6);return `<section class="kboard" data-band="${band}" aria-label="Kitchen dashboard 16 by 9"><header class="kb-header"><div class="kb-brand"><img src="assets/kfc-logo.svg" alt="KFC"><div><strong>ComboFlow <span>/ KITCHEN</span></strong><small>Every order. Every ingredient. One view.</small></div></div><nav aria-label="Prototype navigation"><button onclick="switchChannel('kiosk')">Customer Kiosk</button><button onclick="switchChannel('pos')">Staff POS</button><button class="active">Kitchen Board</button></nav><div class="kb-tools">${liveBadge()}<button class="kb-status-btn" onclick="openStatus()">Kitchen status ◉</button><button onclick="openKitchenPanel('settings')">Controls & assumptions ⚙</button></div></header><div class="kb-metrics"><div class="kb-band"><small>Kitchen signal</small><b>${band}</b><span>Observed-load assumption</span></div><div><small>Median waiting-ticket age</small><b>${s.age}<i>sec</i></b><span>Queued + preparing</span></div><div><small>Open tickets</small><b>${p.open.length}<i>orders</i></b><span>${p.queued.length} queued · ${kitchenTickets.filter(t=>t.status==='preparing').length} preparing · ${kitchenTickets.filter(t=>t.status==='ready').length} ready</span></div><div><small>Projected queue · +10 min</small><b>${f?Math.round(f.base):'—'}<i>${f?'orders':'paused'}</i></b><span>${f?'Range '+Math.floor(f.low+1e-9)+'–'+Math.ceil(f.high-1e-9)+' · sensitivity scenario':'Refresh signal to resume'}</span></div><div><small>Ingredients to watch</small><b>${watch.length}<i>of ${p.inventory.length}</i></b><span>Short / under 5 min cover</span></div><div><small>Signal age</small><b>${s.freshness}<i>sec</i></b><span>${s.freshness>60?'Stale signal':'Fresh synthetic snapshot'}</span></div></div><div class="kb-main"><section class="kb-orders kb-panel"><div class="kb-panel-title"><h2>Priority & dispatch</h2><small>TEAM DECIDES</small></div><div class="kb-groups">${[['urgent','Longest waiting','≥60s'],['batch','Next in line','<60s'],['blocked','Stock check','Cannot start']].map(([key,label,note])=>`<button class="kb-group ${key}" ${p.groups[key].length?'':'disabled'} onclick="${key==='blocked'?"setKitchenView('blocked')":"draftPriority('"+key+"')"}"><b>${p.groups[key].length}</b><strong>${label}</strong><small>${note} · ${key==='blocked'?'View':'Prioritize →'}</small></button>`).join('')}</div><div class="kb-queue-toolbar"><h3>Order queue <small>${all.length}</small></h3><select aria-label="Filter kitchen tickets" onchange="setKitchenView(this.value)">${[['all','All open'],['urgent','Longest waiting'],['batch','Next in line'],['blocked','Stock check'],['preparing','Preparing'],['ready','Ready']].map(([key,label])=>`<option value="${key}" ${kitchenView===key?'selected':''}>${label}</option>`).join('')}</select></div><div class="kb-ticket-list">${tickets.map(t=>{const blocked=t.status==='queued'&&KP.shortage(t,ingredientStock).length;return `<article class="kb-ticket ${t.teamPriority?'priority':''} ${blocked?'blocked':''}"><button class="kb-ticket-info" onclick="openKitchenPanel('ticket','${t.id}')"><img src="${assetUrls[photoMap[t.lines?.[0]?.id]||'chicken-combo.jpg']}" alt=""><span><b>#${t.id} <i>${t.channel}</i></b><strong>${escapeHTML(t.label)}</strong><small>${blocked?'Ingredient shortage':t.teamPriority?'Team priority · confirmed':(t.batchId?'Batch '+t.batchId+' · ':'' )+KP.station(t)}</small></span></button><div class="kb-ticket-action"><b>${t.status==='ready'?'Ready ✓':t.age+'s'}</b><button ${blocked?'disabled':''} onclick="${t.status==='ready'?"openKitchenPanel('ticket','"+t.id+"')":"kitchenStep('"+t.id+"','"+(t.status==='queued'?'preparing':'ready')+"')"}">${t.status==='queued'?'Start →':t.status==='preparing'?'Mark ready':'Details'}</button></div></article>`;}).join('')||'<div class="kb-empty">No tickets in this view.</div>'}</div><div class="kb-pagination"><span>${all.length?'Showing '+(ticketPage*6+1)+'–'+Math.min(all.length,ticketPage*6+6)+' of '+all.length:'No matching tickets'}</span><div><button aria-label="Previous ticket page" ${ticketPage?'':'disabled'} onclick="ticketPage--;render()">←</button><button aria-label="Next ticket page" ${(ticketPage+1)*6<all.length?'':'disabled'} onclick="ticketPage++;render()">→</button></div></div></section><section class="kb-forecast kb-panel"><div class="kb-panel-title"><h2>Last 60 min · next 15</h2><small>SIMULATED</small></div><div class="kb-forecast-value"><b>${f?Math.round(f.base):'—'}</b><span>open tickets at +10 min<br><small>What-if projection · not a wait promise</small></span></div>${trendChart({forecast:p.fresh?p.points:null})}<div class="kb-forecast-controls"><label>Arrivals / min<select aria-label="Incoming orders per minute" onchange="changeForecast('arrival',this.value)">${[.6,1.2,2.4].map(v=>`<option value="${v}" ${arrivalRate===v?'selected':''}>${v} · ${v===.6?'Quiet':v===1.2?'Steady':'Rush'}</option>`).join('')}</select></label><label>Completions / min<select aria-label="Completions per minute" onchange="changeForecast('completion',this.value)">${[.8,1,1.6].map(v=>`<option value="${v}" ${completionRate===v?'selected':''}>${v} · Assumed</option>`).join('')}</select></label></div><p class="kb-formula">Open + (arrivals − completions) × minutes.<br>Shading = sensitivity range, not confidence interval.</p><div class="kb-watch"><h3>Prep watch <span>Next 10 min</span></h3>${watch.length?watch.slice(0,2).map(i=>`<button onclick="openKitchenPanel('ingredient','${i.id}')"><img src="${assetUrls[i.image]}" alt=""><span><b>${i.name}</b><small>${i.onHand} on hand · ${i.reserved} queued</small></span><strong>${i.topUp===null?'Paused':i.topUp+' '+i.unit}<small>${i.topUp===null?'Forecast unavailable':'suggested top-up →'}</small></strong></button>`).join(''):`<p>${p.fresh?'No immediate shortage in this scenario.':'Forecast paused. Refresh the signal.'}</p>`}</div>${renderBatchSuggestion()}<div class="kb-ready"><div><h3>Ready to pair</h3><button onclick="openKitchenPanel('ready')">Manage →</button></div><p>Checked portions · synthetic snapshot</p><div class="ready-pills">${Object.entries(readyExtras).map(([id,n])=>`<span class="${readyDue(id)?'due':''}">${E.addons.find(x=>x.id===id).name}<b>${n}${readyDue(id)?' · re-check':''}</b></span>`).join('')}</div></div></section><section class="kb-inventory kb-panel"><div class="kb-panel-title"><h2>Ingredients on hand</h2><small>${p.inventory.length} ITEMS</small></div><div class="kb-stock-legend"><span>● In stock</span><span>● Watch</span><span>● Short</span><small>Tap a row to adjust / replenish</small></div><div class="kb-stock-table" role="table" aria-label="Ingredient overview"><div class="kb-stock-head" role="row"><span>Ingredient / unit</span><span>On hand</span><span>Queued</span><span>+10 min</span><span>Cover</span></div>${p.inventory.map(i=>{const status=i.free<0?'short':i.free===0||i.cover!==null&&i.cover<5?'watch':'good';return `<button class="kb-stock-row ${status}" aria-label="${i.name}: ${i.onHand} on hand, ${i.reserved} queued, ${i.demand10===null?'forecast paused':i.demand10+' forecast'}" onclick="openKitchenPanel('ingredient','${i.id}')"><span class="kb-stock-name"><img src="${assetUrls[i.image]}" alt=""><span><b>${i.name}</b><small>${i.unit}${incomingStock[i.id]?' · '+incomingStock[i.id]+' incoming':''}</small></span></span><strong>${i.onHand}</strong><span>${i.reserved}</span><span>${i.demand10===null?'—':i.demand10}</span><span class="kb-cover">${i.free<0?'Short':i.cover===null?'—':i.cover+'m'}</span></button>`;}).join('')}</div><div class="kb-stock-note"><b>${band==='High'?'Upsell paused · High load':band==='Safe fallback'?'Rules-only fallback · stale signal':band==='Elevated'?'Prefer ready items / quiet stations':'Upsell enabled · one compatible extra'}</b><button class="kb-manage" onclick="openStatus()">Manage kitchen status →</button><span>Start → deduct once. Plan top-up → no stock change. Receive → add stock.</span><small>Planning units / recipes are illustrative. ${E.VERIFY}</small></div></section></div><footer class="kb-footer"><span>Simulated Contextual Ranking (pre-scripted decision table)</span><div><button onclick="toggleLive()">${liveOn?'❚❚ Pause live demo':'▶ Resume live demo'}</button><button onclick="advanceKitchen(30)">Advance demo 30s</button><button onclick="refreshKitchen()">Refresh signal ↻</button></div><span>No live KDS · No learned AI · Human confirmation required</span></footer></section>${kitchenDetail(p)}`;}

let batchDraft=null,batchSeq=0;
function batchFresh(){return E.band(s)!=='Safe fallback'&&!s.stockStale;}
function renderBatchSuggestion(){const group=KP.batchSuggestions(kitchenTickets,ingredientStock,batchFresh())[0];return `<div class="kb-batching"><div><h3>Prepare together</h3><small>HEURISTIC · TEAM CHECK</small></div>${group?`<strong>${group.ids.map(id=>'#'+id).join(' · ')}</strong><p>${group.units} ${KP.ingredients.find(x=>x.id===group.key).name.toLowerCase()} units · ${group.ids.length} queued orders</p><button onclick="reviewBatch()">Review shared prep →</button>`:`<p>${batchFresh()?'No compatible group with enough stock. Continue individual tickets.':'Suggestion paused. Refresh signal / check availability.'}</p>`}</div>`;}
function reviewBatch(){batchDraft=KP.batchSuggestions(kitchenTickets,ingredientStock,batchFresh())[0]||null;if(!batchDraft)return;log('batch_suggested',{proposal:batchDraft});openKitchenPanel('batch');}
function batchDetail(){if(!batchDraft)return '<p>No current proposal.</p>';return `<p class="eyebrow">SIMULATED SHARED PREP</p><h3>${batchDraft.ids.map(id=>'#'+id).join(' · ')}</h3><p>Shared component: <b>${KP.ingredients.find(x=>x.id===batchDraft.key).name}</b>. Includes the first eligible ticket by team priority, then waiting age (${batchDraft.oldest}s). Up to three existing orders; no waiting for future arrivals.</p><div class="batch-recipe">${Object.entries(batchDraft.needs).map(([id,n])=>`<span>${KP.ingredients.find(x=>x.id===id).name}<b>${n} / ${ingredientStock[id]} on hand</b></span>`).join('')}</div><p class="small muted">Review cooking method, recipe and equipment compatibility with the team. These are illustrative recipe groups, not a validated cooking plan or a time-saving prediction.</p><p class="small">Confirming starts all listed tickets and deducts their full recipe quantities once. Stock and ticket states are checked again.</p><div class="actions"><button class="btn red" onclick="confirmBatch()">Confirm & start group</button><button class="btn white" onclick="skipBatch()">Skip grouping</button></div>`;}
function skipBatch(){log('batch_skipped',{proposal:batchDraft});batchDraft=null;closeKitchenPanel();}
function confirmBatch(){const result=KP.startBatch(kitchenTickets,ingredientStock,batchDraft,batchFresh());if(!result){log('batch_blocked',{proposal:batchDraft});batchDraft=null;closeKitchenPanel();toast('Queue or stock changed. Review a new suggestion.');return;}ingredientStock=result.stock;const id='G'+(++batchSeq);for(const t of kitchenTickets)if(result.ids.includes(t.id)){t.status='preparing';t.batchId=id;}log('batch_confirmed',{batch_id:id,tickets:result.ids,consumed:result.needs});batchDraft=null;kitchenPanel=null;syncKitchen();render();toast('Group '+id+' started by the team.');}
log('run_started');

function chickenCustomizable(){return !!selected?.variantGroups.includes('chicken');}
function variantChoice(){return Object.fromEntries((selected?.variantGroups||[]).map(g=>[g,customization[g]]));}
function customSummary(){return [chickenCustomizable()?customization.chicken+' chicken':null,selected?.variantGroups.includes('drink')?customization.drink:null].filter(Boolean).join(' · ')||'Standard preparation';}
function setCustomization(key,value){if(!selected?.variantGroups.includes(key)||!E.variants[key].some(v=>v.id===value)||(s.unavailableVariants||[]).includes(value))return;customization[key]=value;log('customization_changed',{key,value});render();}
function renderCustomize(d){if(!selected)return '';return `<section class="screen customize-screen">${steps(1)}<p class="eyebrow">MAKE IT YOURS</p><h2>Customize your combo</h2><div class="custom-meal"><div>${foodPhoto(selected.id)}</div><span><h3>${selected.name}</h3><p>${selected.desc}</p><strong>${money(selected.price)}</strong></span></div>${stateNotice(d)}${chickenCustomizable()?`<div class="custom-section"><h3>Choose your chicken</h3><div class="custom-options chicken-options">${E.variants.chicken.map(({id:v,desc:t})=>{const off=(s.unavailableVariants||[]).includes(v);return `<button aria-pressed="${customization.chicken===v}" class="${customization.chicken===v?'selected':''}" ${off?'disabled':''} onclick="setCustomization('chicken','${v}')">${foodPhoto('chickenMain')}<strong>${v}</strong><small>${off?'Unavailable · demo':t}</small><span>${customization.chicken===v?'✓':''}</span></button>`;}).join('')}</div></div>`:''}${selected.variantGroups.includes('drink')?`<div class="custom-section"><h3>Choose your drink</h3><div class="custom-options drink-options">${E.variants.drink.map(({id:v,color:c})=>{const off=(s.unavailableVariants||[]).includes(v);return `<button aria-pressed="${customization.drink===v}" class="${customization.drink===v?'selected':''}" ${off?'disabled':''} onclick="setCustomization('drink','${v}')"><i class="drink-cup" style="--cup:${c}"><b>${v}</b></i><strong>${v}</strong><small>${off?'Unavailable · demo':'Included · demo'}</small><span>${customization.drink===v?'✓':''}</span></button>`;}).join('')}</div></div>`:''}<p class="micro">Price-neutral demo choices. Same drink for the included cups. Recipe, flavor availability and drink options: ${E.VERIFY}. Simulated mapping: Spicy uses one marinade portion per chicken piece; drink flavors share cups.</p>${renderPairing(selected,choiceSource==='manual')}<button class="btn text" onclick="go('${choiceSource==='manual'?'menu':'options'}')">← Change combo</button></section>`;}
function adjustReady(id,delta){if(!Object.hasOwn(readyExtras,id))return;if(!readyExtras[id]&&delta>0)readyAge[id]=0;readyExtras[id]=Math.min(99,Math.max(0,readyExtras[id]+delta));log('ready_snapshot_updated',{id,count:readyExtras[id]});render();}
function readyDue(id){return readyExtras[id]>0&&readyAge[id]>KP.HOLD_LIMIT_S;}
function recheckReady(id){if(!readyExtras[id])return;log('ready_rechecked',{id,count:readyExtras[id],age_s:readyAge[id]});readyAge[id]=0;render();}
function discardReady(id){if(!readyExtras[id])return;log('ready_discarded',{id,count:readyExtras[id],age_s:readyAge[id]});readyExtras[id]=0;readyAge[id]=0;render();}
function readyControls(){return `<p class="small">Staff-checked portions available to pair. These are synthetic counts within the ingredient snapshot, not additional stock. Check holding time and food quality before offering.</p><div class="ready-control-list">${Object.entries(readyExtras).map(([id,n])=>`<div>${foodPhoto(id)}<span><b>${E.addons.find(x=>x.id===id).name}</b><small>${n?(readyDue(id)?'<em class="ready-due">Re-check due</em> · ':'')+'Checked '+Math.round(readyAge[id]/60)+' min ago (demo clock)':'Ready portions'}</small>${n?`<span class="ready-actions"><button class="ready-text" onclick="recheckReady('${id}')">Mark checked</button><button class="ready-text" onclick="discardReady('${id}')">Discard</button></span>`:''}</span><button aria-label="Reduce ready ${id}" onclick="adjustReady('${id}',-1)">−</button><strong>${n}</strong><button aria-label="Increase ready ${id}" onclick="adjustReady('${id}',1)">+</button></div>`).join('')}</div><p class="micro">Confirmed orders reserve these portions. Ingredient deduction still occurs once at Start preparing. Stale signals disable ready-item ranking. High load blocks upsell regardless of ready counts. Portions unchecked for more than ${KP.HOLD_LIMIT_S/60} demo minutes drop out of ready-first ranking until staff mark them checked or discard them. [Assumption] placeholder window, not a KFC holding-time or food-safety standard.</p>`;}
// Simulated kiosk payment step. No money is taken and no card or wallet details are collected.
const payMethods=[['counter','Pay at the counter','Show your order number to our team','▣'],['card','Card (demo)','Tap or insert · simulated terminal','▭'],['qr','QR e-wallet (demo)','Scan to pay · simulated','▦']];
function choosePayment(id){if(page!=='payment'||!payMethods.some(m=>m[0]===id))return;payMethod=id;log('payment_method_selected',{method:id});render();}
function renderPayment(d){if(!selected)return '';const total=selected.price+(kioskAdded?kioskAdded.price:0);return `<section class="screen checkout-screen payment-screen">${steps(3)}<p class="eyebrow">ALMOST THERE</p><h2>How would you like to pay?</h2><p class="muted small">Simulated payment. No money is taken and no card or wallet details are collected.</p>${stateNotice(d)}<div class="summary-row receipt-item"><div class="receipt-photo">${foodPhoto(selected.id)}</div><div><h3>${escapeHTML(selected.name+(kioskAdded?' + '+kioskAdded.name:''))}</h3><p class="custom-receipt">${customSummary()} · ${s.orderMode==='takeaway'?'Take away':'Dine in'}</p></div><b>${money(total)}</b></div><div class="pay-options" role="group" aria-label="Payment method">${payMethods.map(([id,title,sub,icon])=>`<button aria-pressed="${payMethod===id}" class="${payMethod===id?'selected':''}" onclick="choosePayment('${id}')"><span class="pay-icon" aria-hidden="true">${icon}</span><span><strong>${title}</strong><small>${sub}</small></span><span class="choice-check">${payMethod===id?'✓':'○'}</span></button>`).join('')}</div><div class="summary-row"><b>Total to pay</b><b>${money(total)}</b></div><div class="actions"><button class="btn red" ${payMethod?'':'disabled'} onclick="confirmOrder()">${payMethod==='counter'?'Place demo order →':'Pay & place demo order →'}</button><button class="btn white" onclick="go('review')">← Back to review</button></div><p class="micro">${payMethod?'':'Choose a payment method to continue. '}No real payment · ${E.VERIFY}</p></section>`;}
